import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"1.1 So, What Is Blocking Control?","description":"","frontmatter":{"translationSource":{"title":"1.1 那我问你，什么是阻塞控制","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=quUTb9JSv879txqKEKI0BS","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-1-so-tell-me-what-is-production-controlled-by-blocking"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-1-so-tell-me-what-is-production-controlled-by-blocking"}]]},"headers":[],"relativePath":"1-1-so-tell-me-what-is-production-controlled-by-blocking.md","filePath":"logistics/src/page-quUTb9JSv879txqKEKI0BS.md"}'),s={name:"1-1-so-tell-me-what-is-production-controlled-by-blocking.md"};function i(r,e,l,c,p,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="_1-1-so-what-is-blocking-control" tabindex="-1">1.1 So, What Is Blocking Control? <a class="header-anchor" href="#_1-1-so-what-is-blocking-control" aria-label="Permalink to &quot;1.1 So, What Is Blocking Control?&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>quUTb9JSv879txqKEKI0BS</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=quUTb9JSv879txqKEKI0BS" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Last updated: 26-11-16</p><p><span id="source-block-cOjAkmc10z8olELAj3s3mC"></span></p><h2 id="we-need-automatic-control" tabindex="-1">We Need Automatic Control! <a class="header-anchor" href="#we-need-automatic-control" aria-label="Permalink to &quot;We Need Automatic Control!&quot;">​</a></h2><p><span id="source-block-OSs33Rg87xrRr23FlHyMo0"></span></p><h3 id="control-is-everywhere" tabindex="-1">Control Is Everywhere <a class="header-anchor" href="#control-is-everywhere" aria-label="Permalink to &quot;Control Is Everywhere&quot;">​</a></h3><p>From here on, let&#39;s look at Endfield production lines from the perspective of <strong>control</strong>.</p><p>What is <strong>control</strong>? Broadly speaking, it is anything we do to a production line that changes how it operates. Shut down a Refining Unit that converts Originium Ore into Origocrust, for example, and it produces 30 fewer Origocrust and consumes 30 fewer Originium Ore per minute. If you run a belt from that ore supply to a Shredding Unit to make Originium Powder instead, that is another form of <strong>control</strong>.</p><p>In the broadest sense, just about anything you do in your factory counts as <strong>control</strong>, whether you take some parts to build turrets, move machines around, or put out a couple of mining rigs or pumps. Some actions have little effect. What usually matters is <u>control that achieves the production goal we set</u>. That&#39;s why you hear people say they forgot to shut off the Xiragen or let the Cuprium fill storage and need to log in to adjust the line.</p><p>People are lazy, and we can&#39;t spend all our time adjusting a factory. We&#39;d like something else <s>three letters</s> to <strong>control</strong> it for us. This is where <span class="mark-blue"><strong>automatic control</strong></span> comes in. We <u>set a </u><u><strong>condition</strong></u><u>, or </u><u><strong>trigger</strong></u><u>, in advance. When it is met, the line adjusts on its own to achieve the production goal we set</u>.</p><hr><p><span id="source-block-Lx2bUyoi8CJRjyEcr0q8fI"></span></p><h3 id="two-types-of-automatic-control" tabindex="-1">Two Types of Automatic Control <a class="header-anchor" href="#two-types-of-automatic-control" aria-label="Permalink to &quot;Two Types of Automatic Control&quot;">​</a></h3><p>Endfield&#39;s factories lack programmable components such as valves that open at a given stock level. What can we use to set <strong>trigger conditions</strong>? The only widely used options at the moment may be <span class="mark-red"><strong>clock signals and blocking signals</strong></span>.</p><p><span id="source-block-Z6mdADAvF3e1OBMkc4MQyH"></span></p><h4 id="clock-signal-control" tabindex="-1">Clock Signal Control <a class="header-anchor" href="#clock-signal-control" aria-label="Permalink to &quot;Clock Signal Control&quot;">​</a></h4><p>The idea behind <strong>clock signal control</strong> is simple. <u>Set a timer and do something when it goes off.</u></p><p><strong>Clock signal control</strong> mainly asks how to build the desired timer and clock signal, and how to control other production lines when the timer fires.</p><p>Some examples of clock signal control:</p><ul><li><p>I used a clock signal to produce Heavy Xiranite with one Forge of the Sky <a href="/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals">Single-Forge Heavy Xiranite Production with a Clock Signal</a>.</p></li><li><p>The signal-controlled design in the second half of this page.</p></li><li><p>First Type II Disposal Prototype <a href="/endfield-skydoc/optimizing-the-reactor-crucible-trash-can">Optimizing the Reactor Crucible as a Disposal Unit</a>, <a href="/endfield-skydoc/producing-xircon-effluent-in-a-single-reactor-crucible">Producing Xircon Effluent in a Single Reactor Crucible</a>.</p></li></ul><p>This tutorial generally leaves <span class="mark-red"><strong>clock signals</strong></span> aside.</p><p><span id="source-block-bZK26YZ76HqQdceorQf5y1"></span></p><h4 id="blocking-signal-control" tabindex="-1">Blocking Signal Control <a class="header-anchor" href="#blocking-signal-control" aria-label="Permalink to &quot;Blocking Signal Control&quot;">​</a></h4><p>The idea behind <strong>blocking signal control</strong> is just as simple. <u>A blockage propagates upstream, and excess material overflows to another route.</u></p><p><strong>Blocking signal control</strong> likewise asks where to look for a blockage and how to make that signal control other production lines.</p><p>This tutorial focuses on <span class="mark-red"><strong>blocking signals</strong></span>.</p><p><span id="source-block-qxxUQgNM3ODcztb9dyEMbo"></span></p><h2 id="what-can-we-use-as-blocking-signals" tabindex="-1">What Can We Use as Blocking Signals? <a class="header-anchor" href="#what-can-we-use-as-blocking-signals" aria-label="Permalink to &quot;What Can We Use as Blocking Signals?&quot;">​</a></h2><p><span id="source-block-k8JUYPUhl574wPiEOg449E"></span></p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p>This is only the introduction, so let&#39;s look at a few examples. We can identify the blocking part of signals that matter for production and use overflow to control where the flow goes.</p><p><span class="mark-purple">Q: I want to fill </span><span class="mark-purple"><u>storage with Amethyst Bottles</u></span><span class="mark-purple"> before making </span><span class="mark-purple"><u>Cryston Bottles</u></span><span class="mark-purple">.</span></p><p><span class="mark-red">A: Amethyst Bottle storage fills → the Moulding Unit&#39;s output buffer backs up, followed by its input buffer. Excess Amethyst Ore overflows into Cryston Bottle production.</span></p><p><span class="mark-purple">Q: I want </span><span class="mark-purple"><u>Steel Parts available from storage at all times</u></span><span class="mark-purple">, with spare Steel capacity going to Valley Batteries when I don&#39;t need the parts.</span></p><p><span class="mark-red">A: Same principle as above.</span></p><p><span class="mark-purple">Q: I want Cuprium </span><span class="mark-purple"><u>to go into Cuprium Parts first</u></span><span class="mark-purple">, but I want </span><span class="mark-purple"><u>the remaining Cuprium to go into Cuprium Fittings</u></span><span class="mark-purple"> after part storage fills, so a full Cuprium stockpile can&#39;t block Sewage production.</span></p><p><span class="mark-red">A: Cuprium Part storage fills → the return line backs up and Cuprium overflows into the unit making Cuprium Fittings, avoiding a Sewage shortage.</span></p><p><span class="mark-purple">Q: I want Xiranite </span><span class="mark-purple"><u>to meet SC Wuling Battery demand first</u></span><span class="mark-purple">, with the surplus going to other products. That way the line can use up any extra Dense Originium Powder I occasionally bring from the Valley to Wuling.</span></p><p><span class="mark-red">A: Give Xircon production first call on Liquid Xiranite, followed by Heavy Xiranite production → the Liquid Xiranite line feeding Xircon backs up. The line uses all available Dense Originium Powder, whose supply determines Xircon and battery output and Liquid Xiranite use. It also indirectly controls Heavy Xiranite output.</span></p><p><span class="mark-purple">Q: I want to stop the transmuting unit wasting Xiranite and feed it only as fast as its other input allows.</span></p><p><span class="mark-red">A: With Liquid-Gas Transmuting Unit feedback, supply Liquid Xiranite only when enough input liquid is available. As the input liquid accumulates, it blocks the Liquid Xiranite recirculation loop, so Liquid Xiranite overflows into the unit&#39;s feed line.</span></p><p><span class="mark-purple">Q: I want </span><span class="mark-purple"><u>all the raw materials turned into products</u></span><span class="mark-purple">. Even if the required production rate is a complicated fraction, an adaptive design should reach it on its own.</span></p><p><span class="mark-red">A: A bit too complicated to explain here, but the tutorial covers it.</span> <a href="/endfield-skydoc/3-1-the-beginnings-of-automatic-balancing-xiranite-and-originium-powders">3.1 The Beginnings of Automatic Balancing: Xiranite and Originium Powder</a></p><p>We can build or use structures that may become blocked and exploit the resulting changes in flow to make production adjust automatically. Overflow is central to blocking control, since it routes flow differently as conditions change. <strong>The principles of blocking control</strong> cover <strong>how to build these structures, how the flow rates change, and whether the design meets the intended production goal</strong>.</p><p><span id="source-block-0tbsYIllXAnTdtaVMTs8Be"></span></p><h3 id="further-notes" tabindex="-1">Further Notes <a class="header-anchor" href="#further-notes" aria-label="Permalink to &quot;Further Notes&quot;">​</a></h3><blockquote><p>A full stockpile is one way blocking occurs. How the line responds when storage fills is a major topic in blocking control (full-storage dynamics.jpg).</p></blockquote><blockquote><p>For the connection between blocking control and blocking flow theory, see <a href="/endfield-skydoc/4-0-building-the-science-of-blocking-based-production-on-blocking-flow">4.0 Building the Study of Production Controlled by Blocking on Blocking Flow Theory</a> and <a href="/endfield-skydoc/flow-theory-for-idealized-logistics-systems">Flow Theory for Idealized Logistics Systems</a>.</p></blockquote><blockquote><p>If basic line design means making products at rate y* from a given quantity or input rate x*—the finished report looks correct—f(x*) = y*, this article discusses the next level: how the line responds to external changes such as input supply or full product storage, and how to use those responses for more complex production needs. Does f give the correct y for every x in some range? When supply x* changes, does y* reflect the desired result? Or when y* changes, can x* respond appropriately?</p></blockquote><p>Blocking control takes one more step of thinking about the production lines you already have. You may have used it or seen it used before. The important part is understanding how it happens. Let&#39;s start with the simplest layouts and look at Endfield production lines from that perspective.</p><p><a href="/endfield-skydoc/1-2-what-are-the-benefits-of-blocking-based-production">1.2 Basic Concepts and Single-Branch Control (One Input, One Output)</a></p><p><a href="/endfield-skydoc/production-control-and-frontier-research">Production Control and Frontier Research</a></p></div>',1)])])}const g=t(s,[["render",i]]);export{h as __pageData,g as default};
